def build_acl06_handoff(*,batch: dict,manifest: dict,receipt_digest: str,candidate_freeze: dict,search_freeze: dict,datasets: dict,labels: dict,split: dict,environment: dict,budget: dict,object_index: dict,event_ledger: dict,provenance: dict) -> dict:
    body={"schema_version":"1.0.0","handoff_type":"ACL05_TO_ACL06","batch_id":batch["batch_id"],"batch_definition_digest":batch["batch_definition_digest"],"batch_manifest_digest":manifest["batch_manifest_digest"],"freeze_receipt_digest":receipt_digest,"candidate_freeze_digest":candidate_freeze["candidate_freeze_digest"],"search_space_freeze_digest":search_freeze["search_space_freeze_digest"],"dataset_snapshot_set_digest":datasets["dataset_snapshot_set_digest"],"label_contract_set_digest":labels["label_contract_set_digest"],"split_digest":split["split_digest"],"environment_digest":environment["environment_digest"],"budget_digest":budget["budget_digest"],"object_index_digest":object_index["object_index_digest"],"event_ledger_digest":event_ledger["ledger_digest"],"provenance_graph_digest":provenance["graph_digest"],"required_acl06_actions":["PLAN_RESEARCH_DAG","REGISTER_TASK_CONTRACTS","EXECUTE_BOUNDED_RESEARCH"],"forbidden_acl06_actions":["MUTATE_BATCH","MUTATE_SETUP_BEHAVIOR","PROMOTE_DIAGNOSTIC_CANDIDATE","INFER_ALPHA_FROM_FREEZE","AUTHORIZE_EXECUTION","ACTIVATE_CAPITAL"],"claim_ceiling":"RESEARCH_BATCH_FREEZE_REFERENCE_ONLY","live_order_submission_allowed":False,"capital_activation_allowed":False}
